{
  "questions": [
    {
      "n": 1,
      "start": "Ritiene che la possibilità di telelavoro parziale",
      "end": "contribuire a risolvere i problemi di traffico tra Chiasso e Lugano?"
    },
    {
      "n": 2,
      "start": "Considera che affinché il telelavoro parziale sia davvero considerato uno",
      "end": "strumento utilizzabile, gli ambiti fiscali e assicurativi vadano parificati, nel senso di introdurre valori soglia anche a livello fiscale?"
    },
    {
      "n": 3,
      "start": "È disposto a intervenire presso le Autorità federali, come ha fatto il Consiglio di Stato di Ginevra,",
      "end": "affinché la Confederazione ricerchi in tempi rapidi con l’Italia una soluzione durevole per il telelavoro parziale dei frontalieri nel senso di introdurre un limite (1 giorno alla settimana) entro il quale il telelavoro non comporta conseguenze sulla fiscalità dei lavoratori frontalieri italiani?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Il telelavoro permette di diminuire il numero di lavoratori che quotidianamente si spostano",
      "end": "per recarsi al lavoro e quindi contribuisce a ridurre il traffico."
    },
    {
      "n": 2,
      "start": "L’Accordo tra la Svizzera e l’Italia sui frontalieri del 1974 ancora in vigore non prevede alcuna definizione del termine “frontaliere”",
      "end": "e quindi valgono invece i principi previsti dall’art. 15 della Convenzione conclusa tra la Svizzera e la Repubblica italiana per evitare le doppie imposizioni (CDI CH-IT)."
    },
    {
      "n": 3,
      "start": "Fintanto che sono in corso queste trattative e rimane pendente la ratifica dell’Accordo da parte dell’Italia,",
      "end": "riteniamo che non sia opportuno intervenire presso le autorità federali per sollecitare l’apertura di un ulteriore tavolo di lavoro."
    }
  ],
  "submitter": "Cristina Maderni e Sabrina Gendotti",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "Fintanto che sono in corso queste trattative e rimane pendente la ratifica dell’Accordo da parte dell’Italia,",
    "end": "riteniamo che non sia opportuno intervenire presso le autorità federali per sollecitare l’apertura di un ulteriore tavolo di lavoro."
  }
}
